console.log("not-fully-inside/unavailable:", bad.map(n=>({id:n.id, geometryUnavailable:n.geometryUnavailable})));
const paddle = r.nodes.find(n=>n.id==="paddle"), ball=r.nodes.find(n=>n.id==="ball"), brick=r.nodes.find(n=>n.id==="brick-r4-c2");
console.log("paddle screenBounds", JSON.stringify(paddle.screenBounds));
console.log("ball screenBounds", JSON.stringify(ball.screenBounds));
console.log("sample reinforced screenBounds", JSON.stringify(brick.screenBounds));'

